class Solution {
    private String[] words;
    private String result;
    private int[] charToDigit = new int[26];
    private boolean[] usedDigits = new boolean[10];
    private char[] uniqueChars;
    private boolean[] isLeading;
    private int n;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        boolean[] usedChar = new boolean[26];
        boolean[] leading = new boolean[26];

        // Mark all characters used and leading characters
        for (String w : words) {
            int len = w.length();
            for (int i = 0; i < len; i++) {
                char c = w.charAt(i);
                usedChar[c - 'A'] = true;
            }
            if (w.length() > 0) {
                leading[w.charAt(0) - 'A'] = true;
            }
        }
        for (int i = 0; i < result.length(); i++) {
            char c = result.charAt(i);
            usedChar[c - 'A'] = true;
        }
        if (result.length() > 0) {
            leading[result.charAt(0) - 'A'] = true;
        }

        // Collect unique characters
        int count = 0;
        for (int i = 0; i < 26; i++) {
            if (usedChar[i]) count++;
        }
        if (count > 10) return false; // more than 10 unique chars, impossible

        uniqueChars = new char[count];
        isLeading = new boolean[count];
        int idx = 0;
        for (int i = 0; i < 26; i++) {
            if (usedChar[i]) {
                uniqueChars[idx] = (char) (i + 'A');
                isLeading[idx] = leading[i];
                idx++;
            }
        }

        n = uniqueChars.length;
        for (int i = 0; i < 26; i++) charToDigit[i] = -1;
        for (int i = 0; i < 10; i++) usedDigits[i] = false;

        return backtrack(0);
    }

    private boolean backtrack(int pos) {
        if (pos == n) {
            return checkSum();
        }
        char c = uniqueChars[pos];
        int cIndex = c - 'A';
        for (int d = 0; d <= 9; d++) {
            if (usedDigits[d]) continue;
            if (d == 0 && isLeading[pos]) continue; // no leading zero
            charToDigit[cIndex] = d;
            usedDigits[d] = true;
            if (backtrack(pos + 1)) return true;
            charToDigit[cIndex] = -1;
            usedDigits[d] = false;
        }
        return false;
    }

    private boolean checkSum() {
        long sum = 0;
        for (String w : words) {
            long val = wordValue(w);
            if (val == -1) return false; // leading zero or invalid
            sum += val;
        }
        long resVal = wordValue(result);
        if (resVal == -1) return false;
        return sum == resVal;
    }

    private long wordValue(String w) {
        if (w.length() == 0) return -1;
        long val = 0;
        for (int i = 0; i < w.length(); i++) {
            int d = charToDigit[w.charAt(i) - 'A'];
            if (d == -1) return -1;
            val = val * 10 + d;
        }
        // check leading zero
        if (val != 0 && charToDigit[w.charAt(0) - 'A'] == 0) return -1;
        return val;
    }
}

